// ====================================================
// RAMA: TEXTO → Normalización a Binario JSON para IA
// ====================================================
const items = $input.all();
const results = [];

for (const item of items) {
  const body = item.json.body ?? item.json;

  // --- Extraer el texto según formato WhatsApp o genérico ---
  const textContent =
    body?.text?.body ??
    body?.message ??
    body?.content ??
    body?.data ?? '';

  // --- Convertir a bytes UTF-8 ---
  const byteArray = [];
  for (let i = 0; i < textContent.length; i++) {
    const code = textContent.charCodeAt(i);
    byteArray.push(code);
  }

  // --- Representación binaria de cada byte ---
  const binaryRepresentation = byteArray
    .map(b => b.toString(2).padStart(8, '0'));

  // --- Base64 ---
  const base64Content = Buffer.from(textContent, 'utf-8').toString('base64');

  // --- HEX ---
  const hexContent = Buffer.from(textContent, 'utf-8').toString('hex');

  // --- Payload normalizado para la IA ---
  const normalizedPayload = {
    message_id: body?.id ?? `msg_text_${Date.now()}`,
    timestamp: new Date().toISOString(),
    source: body?.source ?? body?.from ?? 'webhook',
    phone_number: body?.from ?? body?.phone ?? 'unknown',
    type: 'text',
    binary_metadata: {
      encoding: 'utf-8',
      mime_type: 'text/plain',
      size_bytes: byteArray.length,
      size_bits: byteArray.length * 8,
      char_count: textContent.length
    },
    content: {
      raw: textContent,
      base64: base64Content,
      hex: hexContent,
      binary_representation: binaryRepresentation,
      byte_array: byteArray
    },
    ai_instruction: `Eres un asistente que interpreta mensajes. Se recibió un MENSAJE DE TEXTO. Contenido original: "${textContent}". Responde al usuario de manera natural y útil.`,
    processing_status: 'ready_for_ai'
  };

  results.push({ json: normalizedPayload });
}

return results;

// ====================================================
// RAMA: VOZ/AUDIO → Normalización a Binario JSON para IA
// ====================================================
const items = $input.all();
const results = [];

for (const item of items) {
  const body = item.json.body ?? item.json;

  // --- Extraer datos del audio (formato WhatsApp o genérico) ---
  const audioData = body?.audio ?? body?.voice ?? {};
  const audioId = audioData?.id ?? body?.media_id ?? `audio_${Date.now()}`;
  const mimeType = audioData?.mime_type ?? 'audio/ogg; codecs=opus';
  const audioBase64 = audioData?.data ?? audioData?.base64 ?? '';
  const durationSec = audioData?.duration ?? null;

  // --- Procesar datos binarios si están disponibles ---
  let magicBytesBinary = [];
  let sizeBytes = 0;
  let hexSample = '';

  if (audioBase64) {
    try {
      const audioBuffer = Buffer.from(audioBase64, 'base64');
      sizeBytes = audioBuffer.length;
      // Primeros 16 bytes como muestra del binario (cabecera del archivo)
      const sample = audioBuffer.slice(0, 16);
      magicBytesBinary = Array.from(sample)
        .map(b => b.toString(2).padStart(8, '0'));
      hexSample = sample.toString('hex');
    } catch (e) {
      magicBytesBinary = [];
    }
  }

  // --- Payload normalizado para la IA ---
  const normalizedPayload = {
    message_id: body?.id ?? `msg_voice_${Date.now()}`,
    timestamp: new Date().toISOString(),
    source: body?.source ?? body?.from ?? 'webhook',
    phone_number: body?.from ?? body?.phone ?? 'unknown',
    type: 'voice',
    binary_metadata: {
      encoding: 'binary',
      mime_type: mimeType,
      media_id: audioId,
      size_bytes: sizeBytes,
      size_bits: sizeBytes * 8,
      duration_seconds: durationSec,
      codec: mimeType.includes('opus') ? 'opus' : mimeType.includes('mp4') ? 'aac' : 'unknown'
    },
    content: {
      media_id: audioId,
      base64: audioBase64,
      magic_bytes_binary: magicBytesBinary,
      hex_sample: hexSample,
      sha256: audioData?.sha256 ?? null,
      download_url: audioData?.url ?? null
    },
    ai_instruction: `Eres un asistente que interpreta mensajes. Se recibió un MENSAJE DE VOZ. Media ID: ${audioId}. Tipo MIME: ${mimeType}. Duración: ${durationSec ?? 'desconocida'} segundos. Para responder: procesa el audio usando el media_id para descargarlo y transcribirlo, luego genera una respuesta apropiada.`,
    processing_status: 'ready_for_ai'
  };

  results.push({ json: normalizedPayload });
}

return results;

// ====================================================
// RAMA: IMAGEN → Normalización a Binario JSON para IA
// ====================================================
const items = $input.all();
const results = [];

for (const item of items) {
  const body = item.json.body ?? item.json;

  // --- Extraer datos de la imagen ---
  const imageData = body?.image ?? body?.photo ?? body?.sticker ?? {};
  const imageId = imageData?.id ?? body?.media_id ?? `img_${Date.now()}`;
  const mimeType = imageData?.mime_type ?? 'image/jpeg';
  const imageBase64 = imageData?.data ?? imageData?.base64 ?? '';
  const caption = imageData?.caption ?? body?.caption ?? '';

  // --- Procesar datos binarios si están disponibles ---
  let magicBytesBinary = [];
  let detectedFormat = mimeType;
  let sizeBytes = 0;
  let hexSample = '';

  if (imageBase64) {
    try {
      const imgBuffer = Buffer.from(imageBase64, 'base64');
      sizeBytes = imgBuffer.length;

      // Detectar formato por magic bytes (primeros 4 bytes)
      const header = imgBuffer.slice(0, 4).toString('hex');
      if (header.startsWith('ffd8ff'))    detectedFormat = 'image/jpeg';
      else if (header.startsWith('89504e47')) detectedFormat = 'image/png';
      else if (header.startsWith('47494638')) detectedFormat = 'image/gif';
      else if (header.startsWith('52494646')) detectedFormat = 'image/webp';
      else if (header.startsWith('25504446')) detectedFormat = 'application/pdf';

      // Primeros 16 bytes en binario (cabecera del archivo)
      const sample = imgBuffer.slice(0, 16);
      magicBytesBinary = Array.from(sample)
        .map(b => b.toString(2).padStart(8, '0'));
      hexSample = sample.toString('hex');
    } catch (e) {
      magicBytesBinary = [];
    }
  }

  // --- Payload normalizado para la IA ---
  const normalizedPayload = {
    message_id: body?.id ?? `msg_img_${Date.now()}`,
    timestamp: new Date().toISOString(),
    source: body?.source ?? body?.from ?? 'webhook',
    phone_number: body?.from ?? body?.phone ?? 'unknown',
    type: 'image',
    binary_metadata: {
      encoding: 'binary',
      mime_type: detectedFormat,
      media_id: imageId,
      size_bytes: sizeBytes,
      size_bits: sizeBytes * 8,
      width: imageData?.width ?? null,
      height: imageData?.height ?? null,
      format_detected_from: imageBase64 ? 'magic_bytes' : 'mime_type_header'
    },
    content: {
      media_id: imageId,
      base64: imageBase64,
      magic_bytes_binary: magicBytesBinary,
      hex_sample: hexSample,
      sha256: imageData?.sha256 ?? null,
      caption: caption,
      download_url: imageData?.url ?? null
    },
    ai_instruction: `Eres un asistente que interpreta mensajes. Se recibió una IMAGEN. Media ID: ${imageId}. Formato detectado: ${detectedFormat}. Caption: "${caption || 'Sin descripción'}". Tamaño: ${sizeBytes} bytes. Para responder: descarga la imagen usando el media_id, analízala visualmente y genera una respuesta contextual.`,
    processing_status: 'ready_for_ai'
  };

  results.push({ json: normalizedPayload });
}

return results;

